```mermaid
classDiagram
    class Calculator {
        +calculate(expression: str) -> str
        -parse(expression: str) -> List[Token]
        -evaluate(tokens: List[Token]) -> Decimal
    }
    class Token {
        -type: TokenType
        -value: Any
        +__init__(type: TokenType, value: Any)
    }
    class TokenType {
        <<enumeration>>
        NUMBER
        PLUS
        MINUS
        MULTIPLY
        DIVIDE
        LPAREN
        RPAREN
    }
    class ShuntingYard {
        +shunt(tokens: List[Token]) -> List[Token]
    }
    class RPNCalculator {
        +calculate(rpn: List[Token]) -> Decimal
    }
    class CalculatorError {
        <<exception>>
        +message: str
    }
    class DivisionByZeroError {
        <<exception>>
    }
    class InvalidExpressionError {
        <<exception>>
    }
    Calculator --> Token : uses
    Calculator --> ShuntingYard : uses
    Calculator --> RPNCalculator : uses
    ShuntingYard --> Token : uses
    RPNCalculator --> Token : uses
    CalculatorError <|-- DivisionByZeroError
    CalculatorError <|-- InvalidExpressionError
```

